command.text:
				&CommandWhenVoucherBeforeInit;
				&CommandWhenVoucherBeforeAddNew;
				&CreateTicket;
				&APICompanyInformationCommandLoadingDeclare;
				&APIGetInvoiceFromMail;

declare @$k int
select @$k = val from options where name = 'l_export_input_invoice'
select @message = @message + 'this._$new = ' + rtrim(@@sysDatabaseName.dbo.FastBusiness$System$GetAuthorize(@@admin, @@userID, 'InputInvoice', 'New'))
select @message = @message + ';this._$edit = ' + rtrim(@@sysDatabaseName.dbo.FastBusiness$System$GetAuthorize(@@admin, @@userID, 'InputInvoice', 'Edit'))

select @message = @message + ';&MultiViewGrid.Loading;;this._$limitExportNumber =' + isnull(cast(@$k as varchar), '1000') + ';&APICompanyInformationCommandLoadingSelect;&APIGetInvoiceFromMailLoadingSelect;this._authorize=1;this._$unit='@@unit';this._$handlerUrl=''~/AppHandler/EInvoiceQuery.ashx'';this._uid=@@userID;this._key = ''' + @ticket + ''';load$Grid(this);'

				&CommandWhenVoucherAfterInit;

script.text:

function load$Grid(g) {
	g._$k = [];
	g._$i = [g._getColumnOrder('stt_rec')];
	g._$t = g._getColumnOrder('tag');
	g._$f = ['stt_rec'];
	g.add_onResponseComplete(on$GridInvoice$ResponseComplete);
	g.add_commandEvent(on$GridInvoice$ExecuteCommand);
	g._oldWaitHTML =  $get(g._id + "_Wait").innerHTML;

	load$MultiViewGrid$&TransferID;(g);
}
function scattering$Grid(g) {
	for (var i = 1; i <= g._rowCount; i++) {
		g._getItem(i, g._getColumnOrder('tag')).disabled = false;
	}
	if (g._gridRefresh) g._$k = [];
	else fill$FlowMulti$InputInvoice$GridQuery(g, true);
}
function dispose$Grid(g) {
	g._$k = g._$i = g._$t = g._$f = null;
	try {g.remove_commandEvent(on$GridInvoice$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridInvoice$ResponseComplete);} catch (ex) {}
	document.body._grid = null;
	g._result = null;
	g._filename = '';
	dispose$MultiGrid$&TransferID;(g);
}
function on$GridInvoice$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, id = g.get_id();
	g._$quickGenerate = false;
	switch (action) {
		case 'Edit':
		case 'Delete':
			var k = g._getColumnOrder('stt_rec');
			for (var i = 0; i < g._$k.length; i++) {
				var val = g._$k[i][k - 1];
				if (g._$k[i][k - 1] == g._getItemValue(g._activeRow, k)) {
					g._$k.splice(i);
					break;
				}
			}

			for (var i = 1; i <= g._rowCount; i++) {
				g._setItemValue(i, g._getColumnOrder('tag'), false);
			}
			g._$k = [];

			break;
		case 'AfterRemoveRow':
				resetDetail&TransferID;(g);
				setTimeout(function(){$get(g._id + "_Wait").innerHTML = g._oldWaitHTML;}, 200)
				if (g._rowCount == 0) {
					resetDetail(g);
				} else {
					if (g._activeRow <= g._rowCount) load$Voucher$Detail(g, g._detailGrid, g._getItemValue(g._activeRow, g._getColumnOrder('stt_rec')), 1);
				}
			break;
		case 'XmlDownload':
			if (g._activeRow > -1) request$XMLDownload(g, action);
			break;
		case 'Print':
			if (g._activeRow == -1) {
				e.type.cancelEvent = true;
				break;
			}
			if (g._activeRow != -1 && g._getItemValue(g._activeRow, g._getColumnOrder('pdf_yn'))) {
				request$PdfHandler(g);
				request$GetTicket(g, 'GetTicket');
				e.type.cancelEvent = true;
			}
			break;
		case 'Execute':
			g._urlReceiveTax = '~/AppService/APIReceiveTax.asmx';
			on$Execute$Menu(g, id, e.type.Value, e.type.cancelEvent);
			break;
		case 'CreateVoucher':
			on$CreateVoucher$Menu(g, id, e.type.Value, e.type.cancelEvent);
			break;
		case 'QuickGenerate':
			g._$quickGenerate = true;
			on$QuickGenerate$Menu(g, id, e.type.Value, e.type.cancelEvent);
			break;
		case 'ImporXML':
			show$FormDeny(g, 'InputInvoiceImportForm');
			break;
		case 'Export':
			var d1 = $func.findMemvar('ngay_ct1', g._memvars), d2 = $func.findMemvar('ngay_ct2', g._memvars);
			if (d1 && dateDiffInDays(d1.NewValue, d2.NewValue) > 30) {
				e.type.cancelEvent = true;
				var msg = g._language == 'v' ? 'Vui lòng chọn khoảng thời gian nhỏ hơn 31 ngày.' : 'Please select the duration less than 31 days.';
				$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
				break;
			}
			if (g._gridTotalRowCount > g._$limitExportNumber) {
				e.type.cancelEvent = true;
				var msg = g._language == 'v' ? 'Số lượng bản ghi kết xuất vượt quá giới hạn cho phép là <span class="Highlight">%s</span>.' : 'The number of records exceeds the maximum allowed of <span class="Highlight">%s</span>.';
				$message.show(msg.replace('%s', g._$limitExportNumber), String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			}
			break;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
function on$Execute$Menu(g, id, action, cancelEvent) {
	switch (action) {
		case '10': // CheckInfo
			if (g._activeRow > -1) {
				g._mst_cn = g._getItemValue(g._activeRow, g._getColumnOrder('mst_cn'));
				getCompanyInformation$Grid(g, g._mst_cn);
			}
			break;
		case '20': // UpdatePdf
			if (g._activeRow > -1) show$Form(g, 'InputInvoicePdfForm');
			break;
		case '25': // Update Searching
			 if (g._activeRow > -1) show$Form(g, 'InputInvoiceUpdateSearching');
			break;
		case '40': // CheckMail
			if (!g._denyNew) g.request(g, 'CheckMail', 'CheckMail', []);
			else $message.show($df.getResources(g._language, 'Message.NotAccess'), String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			break;
		case '60': // Login
			busy$Page(g, true);
			Sys.Net.WebServiceProxy.invoke($func.resolveClientUrl(g._urlReceiveTax, g._baseUrl), 'GetCaptcha', false, {}, onRequest$Completed$GetCaptcha, onRequest$Failed$GetCaptcha, g._id);
			break;
		case '70': // Import
			show$FormDeny(g, 'InputInvoiceTaxImportForm');
			break;
		case '80': // Delete Records
			var s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
			if (isCheck$Grid(g)) $message.show(g._getResources("Message.ConfirmDelete"), 0, String.format('deleteData(\'{0}\');', id), s);
			break;
		default:
			break;
	}
}
function on$CreateVoucher$Menu(g, id, action, cancelEvent) {
	var msg = g._language == 'v' ? 'Có nhiều hơn 1 bản ghi được chọn, vui lòng thực hiện lại.' : 'There exists multiple selected invoice.';
	if (action == '10') {// Update Voucher Code
		if (!g._$edit) $message.show($df.getResources(g._language, 'Message.NotAccess'), String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			else show$Form(g, 'InputInvoiceUpdateVCRefForm');
	} else {
		c = action.split(':');
		g._$gridController = c[1];
		if (c.length > 2 && c[2] == '1' && g._$k.length > 1) $message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
		else do$CreateVoucher(g, c[0]);
		cancelEvent = true;
	}
}
function onRequest$Completed$GetCaptcha(result, id) {
	var g = $find(id);
	busy$Page(g, false);
	if (!result) $message.show(g._language == 'v' ? 'Phát sinh lỗi trong quá trình thực hiện.' : 'The process was failed.');
	g._ckey = result.CKey;
	g._captcha = result.CaptchaSVG;
	show$Form(g, 'InputInvoiceTaxLoginForm');
}
function onRequest$Failed$GetCaptcha(result, id) {busy$Page($find(id), false);}
function do$CreateVoucher(g, voucherCode, quick) {
	if (!isCheck$Grid(g)) return;

	g._$result = '';
	g._$voucherCode = voucherCode;
	g._$inputInvoiceLength = g._$k.length;

	if (!getDataRequest(g, 1)) return;

	if (g._$voucherID) g.request(g, 'CheckValidBeforeGetInvoiceData', 'CheckValidBeforeGetInvoiceData', [['sttRec', 'String', g._$voucherID], ['ngay_ct', 'String', g._$voucherDate], ['quick', 'Boolean', g._$quickGenerate]]);
}
/* </flatten> */
function on$GridInvoice$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, v = g._language == 'v';
	switch (context) {
		case 'XmlDownload':
			var uid = result[1].Value;
			if (uid != '') {
				var r = $get('requestFormData');
				if (!r) r = $func.requestFormData();
				var query = '?a=0&d=App&t=&TransferID;&table=&BaseTable;&c=&BaseTable;&k=' + g._key + '&u=' + uid;
				r.action = $func.resolveClientUrl('~/AppHandler/EInvoiceXML.ashx' + query, g._baseUrl);
				if (!$func.isIE) r.target = '_blank';
				r.submit();
			}
			g._key = result[0].Value;
			if (g._activeCell) g._activeCell.focus();
			break;
		case 'GetTicket':
			g._key = result[0].Value;
			break;
		case 'CheckInfo':
			g._info$status = result[0].Value;
			show$Form(g, 'InputInvoiceInformation');
			break;
		case 'CheckMail':
			if (!result[0].Value) $message.show(v ? 'Hiện chưa có thông tin thư (Email) cần xử lý.' : 'There is no email to process.');
			else {
				var s = String.format('$find(\'{0}\')._focusWhenTabChanged();', g._id);
				var e = v ? 'Hệ thống sẽ đồng bộ dữ liệu từ thư điện tử, bạn có chắc chắn thực hiện không?' : 'The system will parse and extract data from notification on issuing e-Invoice emails. Are you sure to perform?';
				$message.show(e, 0, String.format('request$ScheduletMail($find(\'{0}\'));', g._id), s);
			}
			break;
		case 'GetInvoiceData':
			if (result[0].Value == 'NotAuthorize') {
				$message.show($df.getResources(g._language, 'Message.NotAccess'));
				return;
			}
			result.forEach(function(array) {array.shift();});
			if (!result.length) return;
			g._$result = result;
			g.showForm('InputInvoiceGeneralImportForm');
			busy$Page(g, false);
			break;
		case 'CheckValidBeforeGetInvoiceData':
			g._checkStatus = result[0].Value;
			if (g._checkStatus == '1') {
				var msg = v ? '<span class="Highlight">Trạng thái</span> không hợp lệ.' : '<span class="Highlight">Status</span> is invalid.';
				$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
				return;
			} else if (g._checkStatus == '2') {
				var msg = v ? '<span class="Highlight">Trạng thái chứng từ</span> không hợp lệ.' : '<span class="Highlight">Voucher Status</span> is invalid.';
				$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
				return;
			} else if (g._checkStatus == '3' && g._$quickGenerate) {
				var msg = v ? 'MST người bán <span class="Highlight">%s</span> không hợp lệ.' : 'Seller''s Tax Code <span class="Highlight">%s</span> is invalid.';
				$message.show(msg.replace('%s', result[1].Value), String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
				return;
			} else {
				if (!checkInvoiceData(g, g._$voucherCode)) return;
				if (g._$quickGenerate) {
					g._$customer = result[1].Value;
					g._$customerName = result[2].Value;
					g._$account = result[3].Value;
					g._$accountName = result[4].Value;
					g._$taxCode = result[5].Value;
					g.showForm(g._$gridController + 'AutoGenerateVoucher');
					return;
				}
				g.request(g, 'GetInvoiceData', 'GetInvoiceData', [['stt_rec', 'String', g._$voucherID], ['ma_ct', 'String', g._$voucherCode], ['ngay_ct1', 'String', g._$dateFrom], ['ngay_ct2', 'String', g._$dateTo], ['controller', 'String', g._$gridController]]);
			}
			break;
		case 'DeleteData':
			var val = result[0].Value;
			if (val) {
				var mess = result[1].Value;
				if (mess == '$NotAuthorized') {
					$message.show($df.getResources(g._language, 'Message.NotAccess'));
					return;
				} else $message.show(mess, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			} else  {
				g.goToPage(-1);
				g._$k = [];
			}

			break;
		default:
			break;
	}
}
function onRequest$Completed$DeletePDF(result, id) {}
function onRequest$Failed$DeletePDF(result, id) {}

function init$Toolbar&ImportXmlIdentity;(g) {document.body._grid = g;}
function on$Toolbar&ImportXmlIdentity;$Fail(z) {
	var g = document.body._grid;
	if (z.messageID == '@@messageID') {
		init$Toolbar&ImportXmlIdentity;(g);
		return;
	}

	var e = (g._language == 'v' ? 'Dữ liệu trong tệp không có hoặc không hợp lệ.' : 'The content of the data file is empty or invalid.');
	g._result = null;
	g._filename = '';
	$message.show(e, String.format('init$Toolbar&ImportXmlIdentity;($find(\'{0}\'));', g.get_id()));
}
function set$Toolbar&ImportXmlIdentity;$ImportResult(z) {
	var g = document.body._grid;
	g._result = z.result;
	if (g._result[0][0].trim() == '' || checkVersion(g._result[0][0].toString(), '&XMLVersion;') == -1) {
		var e = g._language == 'v' ? 'Phiên bản XML hiện tại không hợp lệ.' : 'The version of XML file is invalid.';
		$message.show(e, String.format('$find(\'{0}\')._busy = false;parent.$func.hideWait(\'{0}\');', document.body._form._id));
		return;
	}
	if (document.body._form) document.body._form.closeDialog();
	init$Toolbar&ImportXmlIdentity;(g);
	window.setTimeout(function() {g.executeCommand({commandName: 'New', commandArgument: '0'});}, 50);
}
function request$PdfHandler(g) {
	var s = g._getItemValue(g._activeRow, g._getColumnOrder('stt_rec')),  p = g._getItemValue(g._activeRow, g._getColumnOrder('ngay_ct')).z.format('yyyyMMdd');
	var form = $get('requestFormData'), filename = p + s + '.pdf';
	if (!form) form = $func.requestFormData();

	var query = {Unit: '', Controller: '&TransferID;', Name: filename, Key: g._key, 'Database': '', UserID: g._uid, Language: g._language, Partion: p};
	$get('query', form).value = Sys.Serialization.JavaScriptSerializer.serialize(query);
	form.action = $func.resolveClientUrl('~/AppHandler/PdfHandler.ashx', g._baseUrl);
	form.target = '_blank';
	form.submit();
}

/* <flatten type="Javascript"> */
function get$FileName(s) {
	var p = s.lastIndexOf('\\');
	if (p != -1) {return s.substring(p + 1);}
	else {return s;}
}
function getCompanyInformation$Grid(g, t) {
	var url = g._url$API;
	var query = Sys.Serialization.JavaScriptSerializer.serialize({'taxCode': t});
	Sys.Net.WebServiceProxy.invoke($func.resolveClientUrl(g._url$Service, g._baseUrl), g._service$Method, false, {
		url: url,
		Query: query
	}, onRequest$Completed$Grid, onRequest$Failed$Grid, g._id);
}
function onRequest$Completed$Grid(r, id) {
	if (r == '') return;
	var g = $find(id), d = JSON.parse(r);
	if (d['TaxCode'] == null || d['TaxCode'] != g._mst_cn) {
		var e = (g._language == 'v' ? 'Không tìm thấy thông tin người bán.' : 'The seller information is invalid.');
		$message.show(e, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
		return;
	}
	g._info = d;
	request$StatusTaxCode(g, d['Status']);
}
function onRequest$Failed$Grid(e, id) {
	var g = $find(id);
	var e = (g._language == 'v' ? 'Không tìm thấy thông tin người bán.' : 'The seller information is invalid.');
	$message.show(e, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
}
function request$XMLDownload(g, a) {g.request(g, 'XmlDownload', a, [['stt_rec', 'String', g._getItemValue(g._activeRow, g._getColumnOrder('stt_rec'))], ['keyTicket', 'String', g._key]]);}
function request$GetTicket(g, a) {g.request(g, 'GetTicket', a, []);}
function request$StatusTaxCode(g, m) {g.request(g, 'CheckInfo', 'CheckInfo', [['ma_tt', 'String', m]]);}
function show$Form(g, c) {(g._authorize == 1) ? g.showForm(c) : $message.show($df.getResources(g._language, 'Message.NotAccess'));}
function show$FormDeny(g, c) {(g._authorize == 1) && (!g._denyNew) ? g.showForm(c) : $message.show($df.getResources(g._language, 'Message.NotAccess'));}
function busy$Page(f, type) {
	var id = f._id;
	if (type) $func.showWait(id);
	else $func.hideWait(id);
	//$func.enableButtons(!type);
}
function dateDiffInDays(d1, d2) {
	var u1 = Date.UTC(d1.getFullYear(), d1.getMonth(), d1.getDate()), u2 = Date.UTC(d2.getFullYear(), d2.getMonth(), d2.getDate());
	return Math.floor((u2 - u1) / 86400000);
}
function setValue$Array(a, f, v) {for (var i = 0; i < f.length; i++) Array.add(a, {Name: f[i], OldValue: null, NewValue: v[i] , Modified: true, Items: []});}
function checkInvoiceData(g, voucherCode) {
	var k1 = g._getColumnOrder('stt_rec') - 1, k2 = g._getColumnOrder('ngay_ct') - 1, k3 = g._getColumnOrder('mst_cn') - 1, k4 = g._getColumnOrder('ma_nt') - 1, k5 = g._getColumnOrder('status') - 1, k6 = g._getColumnOrder('ma_ct_gs') - 1, k7 = g._getColumnOrder('tc_hd') - 1, k8 = g._getColumnOrder('ma_dvcs') - 1, k9 = g._getColumnOrder('tt_gs') - 1;
	var length = g._$k.length, maTc = '', temp = '', v = g._language == 'v';
	var msg1 = v ? '<span class="Highlight">%s1</span> không hợp lệ.' : '<span class="Highlight">%s2</span> is invalid.',
		msg2 = v ? 'MST hoặc ngoại tệ khác nhau trong các bản ghi đã chọn.' : 'There existed either multiple foreign currency or tax code on the selected records.',
		msg3 = v ? 'Không có dữ liệu! Nhấn <span class="Highlight">Làm mới</span> để xem lại kết quả hiển thị.' : 'No Data! Click <span class="Highlight">Refresh</span> to update the information displayed.',
		msg4 = v ? '<span class="Highlight">%s1</span> không hợp lệ. Nhấn <span class="Highlight">Làm mới</span> để xem lại kết quả hiển thị.' : '<span class="Highlight">%s2</span> is invalid. Click <span class="Highlight">Refresh</span> to update the information displayed.',
		focusWhenTabChanged = String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id());

	for (var i = 0; i < length; i++) {
		var r = g._$k[i];
		if ($func.trim(r[k8]) != g._$unit) {
			$message.show(msg1.replace('%s1', 'Đơn vị').replace('%s2', 'Unit'), focusWhenTabChanged);
			return false;
		}
		if ($func.trim(r[k7]) == '4' || $func.trim(r[k7]) == '6') {
			$message.show(msg1.replace('%s1', 'Tình trạng').replace('%s2', 'Authentication Status'), focusWhenTabChanged);
			return false;
		}
		if ($func.trim(r[k5]) == '*' || $func.trim(r[k5]) == '4') {
			$message.show(msg4.replace('%s1', 'Trạng thái').replace('%s2', 'Status'), focusWhenTabChanged);
			return false;
		}
		if ($func.trim(r[k9]) == '2') {
			$message.show(msg4.replace('%s1', 'Trạng thái chứng từ').replace('%s2', 'Voucher Status'), focusWhenTabChanged);
			return false;
		}

		if (i + 1 < g._$k.length && !g._$quickGenerate) {
			if ($func.trim(r[k4]) != $func.trim(g._$k[i + 1][k4])) {
				$message.show(msg2, focusWhenTabChanged);
				return false;
			}
			if (voucherCode != 'PN1' && voucherCode != 'PN2' && voucherCode != 'PC1' && voucherCode != 'BN1' && voucherCode != 'PK1' && voucherCode != 'HD9' && voucherCode != 'PN9' && $func.trim(r[k3]) != $func.trim(g._$k[i + 1][k3])) {
				$message.show(msg2, focusWhenTabChanged);
				return false;
			}
		}
	}
	return true;
}
function indexTaxRate(a, index, val) {
	for (var i = 0; i < a.length; i++) {
		if (a[i][index] == val) return i;
	}
	return -1;
}
function set$DefaultPositionGrid(g) {
	g._scrollLeft = 0;
	g._changePosition(1, 0);
	g._divGrid.scrollLeft = 0;
	g._divHeader.scrollLeft = 0;
}
function search(f, arr, name) {
	if (name.indexOf('%') != -1) name = name.replace('%l', f._language == 'v' ? '' : '2');
	for (var i = 0; i < arr.length; i++) {
		if (arr[i].name === name) return arr[i].value;
	}
}
function beforeDrillDownBatch(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn))) || $func.trim(g._getItemValue(g._activeRow, g._getColumnOrder('status'))) != '4';}
function removeTagRow$FlowMulti$InputInvoice(g, r) {
	var key = [];
	for (var k = 0; k < g._$f.length; k++) {
		key[k] = g._getItemValue(r, g._$i[k]);
	}

	var tagIndex = getTagRow$FlowMulti$InputInvoice(g, key);
	if (tagIndex >= 0) g._$k.splice(tagIndex, 1);
}

function fill$FlowMulti$InputInvoice$GridQuery(g, b) {
	if (b && g._$k.length == 0) return;

	for (var r = 1; r <= g._rowCount; r++) {
		var key = [];
		for (var k = 0; k < g._$f.length; k++) {
			key[k] = g._getItemValue(r, g._$i[k]);
		}
		var tagIndex = getTagRow$FlowMulti$InputInvoice(g, key);
		if (tagIndex > -1) {
			if (g._$t) g._setItemValue(r, g._$t, true);
