css.text:

div.GroupExecute{background-image:url(../images/Execute.png);background-repeat:no-repeat;background-position:0 0;}
div.TextGroupExecute{background-image:url(../images/TextCalculate.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.GroupExecuteOverGreen, div.TextGroupExecuteOverGreen{background-position:0 -22px;}

div.GroupCreateVoucher{background-image:url(../images/CreateVoucher.png);background-repeat:no-repeat;background-position:0 0;}
div.TextGroupCreateVoucher{background-image:url(../images/TextCreateVoucher.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.GroupCreateVoucherOverGreen, div.TextGroupCreateVoucherOverGreen{background-position:0 -22px;}

div.GroupQuickGenerate{background-image:url(../images/QuickVoucher.png);background-repeat:no-repeat;background-position:0 0;}
div.TextGroupQuickGenerate{background-image:url(../images/TextQuickVoucher.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.GroupQuickGenerateOverGreen, div.TextGroupQuickGenerateOverGreen{background-position:0 -22px;}

div.XmlDownload{background-image:url(../Images/Download.png);background-repeat:no-repeat;background-position:0 0;}
div.ImporXML{background-image:url(../images/Upload.png);background-repeat:no-repeat;background-position:0 0;}
div.XmlDownloadOverGreen{background-position:0 -22px;}, div.ImporXMLOverGreen{background-position:0 -22px;}

.DetailHyperlink:hover {text-decoration:underline;cursor:pointer;}
div.InputInvoiceDiv{width:100%;height:100%;background-color:#edf5ff;padding:4px;color:#444}
.ViewTable{white-space:nowrap;font-family:"Tahoma";font-size:11px;color:#444;overflow:auto;height:100%;width:100%;display: inherit;}
.ViewCell{padding:3px 4px 4px 4px;}
.ViewField{color: #326db5;display:inline;white-space:wrap;}
.ViewBreak{background-color:#fff;border-top-color:#ced3de;border-top-style:solid;border-top-width:1px;display:block;height:1px;margin-bottom:1px;margin-left:8px;margin-right:0;margin-top:1px;overflow-x:hidden;overflow-y:hidden;padding-bottom:0;padding-left:0;padding-right:0;padding-top:0}
.ViewTable::-webkit-scrollbar-corner,.ViewTable::-webkit-scrollbar-track{background-color:#f9f9f9}.ViewTable::-webkit-scrollbar-thumb{background-color:#aac6eb;background-clip:padding-box;border:3px solid transparent;border-radius:20px}.ViewTable::-webkit-scrollbar-thumb:active,.ViewTable::-webkit-scrollbar-thumb:hover{background-color:#8ca3c2!important}.ViewLabelDescription{color:#008100}
.dhxlayout_base_dhx_skyblue div.dhx_cell_layout.dhxlayout_collapsed_h div.dhx_cell_hdr{line-height:28px !important;height:28px !important;}
